package local.skyfamily;
import android.app.*;import android.content.DialogInterface;import android.os.Build;import android.text.InputType;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
final class NativePickers {
 static final int DATE=1,BIRTHDAY=2,TIME=3,DATETIME=4;static final WeakHashMap<View,Integer> bound=new WeakHashMap<>();
 static int kind(EditText edit){String hint=String.valueOf(edit.getHint()).toUpperCase(Locale.US);int input=edit.getInputType(),type=input&InputType.TYPE_MASK_CLASS,variation=input&InputType.TYPE_MASK_VARIATION;if(hint.contains("YYYY-MM-DD"))return hint.contains("HH:MM")?DATETIME:DATE;if(hint.contains("MM-DD"))return BIRTHDAY;if(hint.contains("HH:MM")||hint.equals("TIME")||hint.equals("CLOCK TIME"))return TIME;if(type==InputType.TYPE_CLASS_DATETIME)return variation==InputType.TYPE_DATETIME_VARIATION_TIME?TIME:variation==InputType.TYPE_DATETIME_VARIATION_DATE?DATE:DATETIME;return 0;}
 static void bind(FrameActivity host,View view){if(bound.containsKey(view))return;if(view instanceof CalendarPane){bound.put(view,DATE);CalendarPane pane=(CalendarPane)view;pane.monthTitle.setFocusable(true);pane.monthTitle.setContentDescription("Choose calendar date");pane.monthTitle.setOnClickListener(button->calendar(host,pane));pane.selectedLabel.setFocusable(true);pane.selectedLabel.setContentDescription("Choose selected calendar date");pane.selectedLabel.setOnClickListener(button->calendar(host,pane));return;}if(!(view instanceof EditText))return;EditText edit=(EditText)view;int kind=kind(edit);if(kind==0)return;bound.put(edit,kind);edit.setInputType(InputType.TYPE_NULL);edit.setKeyListener(null);edit.setCursorVisible(false);edit.setFocusable(true);edit.setFocusableInTouchMode(true);if(Build.VERSION.SDK_INT>=21)edit.setShowSoftInputOnFocus(false);edit.setOnClickListener(button->open(host,edit,kind));edit.setOnKeyListener((button,key,event)->{if(key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_SPACE){if(event.getAction()==KeyEvent.ACTION_UP)open(host,edit,kind);return true;}return false;});}
 static Calendar parsed(String value,String pattern){Calendar now=Calendar.getInstance();try{SimpleDateFormat format=new SimpleDateFormat(pattern,Locale.US);format.setLenient(false);ParsePosition position=new ParsePosition(0);Date date=format.parse(value,position);if(date!=null&&position.getIndex()==value.length())now.setTime(date);}catch(Exception ignored){}return now;}
 static boolean live(FrameActivity host,View view,int stamp){return !host.isFinishing()&&host.revision==stamp&&view.getWindowToken()!=null;}
 static void set(FrameActivity host,EditText edit,int stamp,String value){if(live(host,edit,stamp))edit.setText(value);}
 static Calendar chosen(int year,int month,int day){Calendar result=Calendar.getInstance();result.clear();result.set(year,month,day,12,0,0);return result;}
 static void open(FrameActivity host,EditText edit,int kind){if(host.isFinishing())return;final int stamp=host.revision;String value=edit.getText().toString().trim(),hint=String.valueOf(edit.getHint());if(kind==TIME){Calendar now=parsed(value,"HH:mm");new TimePickerDialog(host,(picker,hour,minute)->set(host,edit,stamp,String.format(Locale.US,"%02d:%02d",hour,minute)),now.get(Calendar.HOUR_OF_DAY),now.get(Calendar.MINUTE),android.text.format.DateFormat.is24HourFormat(host)).show();return;}final boolean iso=value.contains("T");Calendar initial=kind==BIRTHDAY?parsed("2000-"+(value.isEmpty()?"01-01":value),"yyyy-MM-dd"):parsed(value,kind==DATETIME?(iso?"yyyy-MM-dd'T'HH:mm":"yyyy-MM-dd HH:mm"): "yyyy-MM-dd");if(kind==BIRTHDAY)initial.set(Calendar.YEAR,2000);final int hour=initial.get(Calendar.HOUR_OF_DAY),minute=initial.get(Calendar.MINUTE);DatePickerDialog dialog=new DatePickerDialog(host,(picker,year,month,day)->{if(!live(host,edit,stamp))return;String date=String.format(Locale.US,"%04d-%02d-%02d",year,month+1,day);if(kind==BIRTHDAY)set(host,edit,stamp,String.format(Locale.US,"%02d-%02d",month+1,day));else if(kind==DATETIME)new TimePickerDialog(host,(clock,h,m)->set(host,edit,stamp,date+(iso?"T":" ")+String.format(Locale.US,"%02d:%02d",h,m)),hour,minute,android.text.format.DateFormat.is24HourFormat(host)).show();else set(host,edit,stamp,date);},initial.get(Calendar.YEAR),initial.get(Calendar.MONTH),initial.get(Calendar.DAY_OF_MONTH));if(kind==BIRTHDAY){dialog.setTitle("Birthday / month and day only");dialog.getDatePicker().setMinDate(chosen(2000,0,1).getTimeInMillis());dialog.getDatePicker().setMaxDate(chosen(2000,11,31).getTimeInMillis());}if(hint.toLowerCase(Locale.US).contains("optional"))dialog.setButton(DialogInterface.BUTTON_NEUTRAL,"Clear",(button,which)->set(host,edit,stamp,""));dialog.show();}
 static void calendar(FrameActivity host,CalendarPane pane){if(host.isFinishing())return;int stamp=host.revision;Calendar date=parsed(pane.selected,"yyyy-MM-dd");new DatePickerDialog(host,(picker,year,month,day)->{if(!live(host,pane,stamp)||!pane.flush())return;Calendar target=chosen(year,month,day);pane.month.setTime(target.getTime());pane.month.set(Calendar.DAY_OF_MONTH,1);pane.select(target.getTimeInMillis());pane.render();},date.get(Calendar.YEAR),date.get(Calendar.MONTH),date.get(Calendar.DAY_OF_MONTH)).show();}
}
